// src/capture/bar.js
function mountCaptureBar(parent, plugin) {
  const rec = plugin.capture;
  const root = parent.createDiv({ cls: "if-cap" });
  let timeEl = null;
  let timer = 0;
  const btn = (icon, label, onClick, cls = "") => {
    const b = root.createEl("button", { cls: "if-cb " + cls, attr: { type: "button", "aria-label": label, title: label } });
    b.createSpan({ cls: "ico ico-" + icon });
    b.addEventListener("mousedown", (e) => e.preventDefault());
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      Promise.resolve(onClick()).catch((err2) => console.error(err2));
    });
    return b;
  };
  const render = () => {
    root.empty();
    const sup = recordingSupport();
    const on = rec.active;
    const can = rec.can();
    if (sup.ok) {
      btn(on ? "stop" : "record", on ? "Stop and save the recording" : "Start recording the screen", () => rec.toggle(), on ? "is-rec" : "is-idle-rec");
      if (on) btn(rec.state === "paused" ? "play" : "pause", rec.state === "paused" ? "Continue recording" : "Pause recording", () => rec.state === "paused" ? rec.resume() : rec.pause());
      timeEl = root.createDiv({ cls: "if-cap-time" + (on ? " is-on" : "") + (rec.state === "paused" ? " is-paused" : "") });
      timeEl.setText(on ? clock(rec.elapsed()) : "00:00");
      btn("mic", rec.micOn ? "Microphone: on (click to mute)" : "Microphone: off (click to turn on)", () => rec.toggleMic(), (rec.micOn ? "" : "is-off ") + (can.mic ? "" : "is-na"));
      btn("read", rec.sysOn ? "Computer sound: on (Windows)" : "Computer sound: off", () => rec.toggleSystem(), (rec.sysOn ? "" : "is-off ") + (can.sys ? "" : "is-na"));
    } else {
      btn("attach", "Add a recording made with the device's own screen recorder", () => rec.attachFile());
      root.createDiv({ cls: "if-cap-note", text: "Use the device's screen recorder, then add the video." });
    }
    btn("camera", "Screenshot: drag over an area, it is copied to the clipboard", () => takeScreenshot(plugin));
    btn("sliders", "Capture settings", () => {
      plugin.app.setting.open();
      plugin.app.setting.openTabById(plugin.manifest.id);
    });
  };
  const tick = () => {
    if (timeEl && rec.active) timeEl.setText(clock(rec.elapsed()));
  };
  render();
  const off = rec.onChange(render);
  timer = window.setInterval(tick, 500);
  return {
    destroy() {
      off();
      window.clearInterval(timer);
      root.remove();
    }
  };
}

// src/panel/capture-section.js
function captureSection(plugin) {
  let bar = null;
  return {
    id: "capture",
    title: "Capture",
    mount(body) {
      bar = mountCaptureBar(body, plugin);
    },
    destroy() {
      if (bar) bar.destroy();
      bar = null;
    }
  };
}

