function pomodoroSection(plugin) {
  const p = plugin.pomodoro;
  let off = null;
  return {
    id: "pomodoro",
    title: "Pomodoro",
    mount(body) {
      body.empty();
      const layout = body.createDiv({ cls: "acp-pomo-layout" });
      const ring = layout.createDiv({ cls: "acp-pomo" });
      const svgNS = "http://www.w3.org/2000/svg";
      const svg = document.createElementNS(svgNS, "svg");
      svg.setAttribute("viewBox", "0 0 120 120");
      svg.setAttribute("class", "acp-pomo-ring");
      const bg = document.createElementNS(svgNS, "circle");
      bg.setAttribute("cx", "60");
      bg.setAttribute("cy", "60");
      bg.setAttribute("r", "52");
      bg.setAttribute("class", "acp-pomo-bg");
      const fg = document.createElementNS(svgNS, "circle");
      fg.setAttribute("cx", "60");
      fg.setAttribute("cy", "60");
      fg.setAttribute("r", "52");
      fg.setAttribute("class", "acp-pomo-fg");
      fg.setAttribute("transform", "rotate(-90 60 60)");
      svg.appendChild(bg);
      svg.appendChild(fg);
      ring.appendChild(svg);
      const mid = ring.createDiv({ cls: "acp-pomo-mid" });
      const clock3 = mid.createDiv({ cls: "acp-pomo-clock" });
      const phase = mid.createDiv({ cls: "acp-pomo-phase" });
      const col = layout.createDiv({ cls: "acp-pomo-col" });
      const btn = (name, label, extra = "") => {
        const b = col.createEl("button", { cls: "acp-round" + extra, attr: { "aria-label": label, title: label } });
        b.createSpan({ cls: "ico ico-" + name });
        return b;
      };
      const startBtn = btn("play", "Start", " acp-round-main");
      const resetBtn = btn("reset", "Reset");
      const skipBtn = btn("skip", "Skip to the next phase");
      const info = body.createDiv({ cls: "acp-hint acp-center" });
      const C = 2 * Math.PI * 52;
      fg.setAttribute("stroke-dasharray", String(C));
      const render = () => {
        clock3.setText(fmtClock(p.remaining));
        phase.setText(PHASES[p.phase].label);
        body.toggleClass("is-break", p.phase !== "work");
        body.toggleClass("is-running", p.running);
        const frac = p.total ? 1 - p.remaining / p.total : 0;
        fg.setAttribute("stroke-dashoffset", String(C * (1 - Math.min(1, Math.max(0, frac)))));
        startBtn.querySelector(".ico").className = "ico ico-" + (p.running ? "pause" : "play");
        startBtn.setAttribute("title", p.running ? "Pause" : p.remaining < p.total ? "Resume" : "Start");
        info.setText("\u{1F345} today: " + p.todayCount + "   \xB7   round: " + p.cycle + "/" + (plugin.settings.pomoLongEvery || 4));
      };
      startBtn.addEventListener("click", () => p.toggle());
      resetBtn.addEventListener("click", () => p.reset());
      skipBtn.addEventListener("click", () => p.skip());
      off = p.onChange(render);
      render();
    },
    destroy() {
      if (off) off();
    }
  };
}

