// src/tts/wav.js
function resample(samples, from, to) {
  if (from === to) return samples;
  const ratio = from / to;
  const n2 = Math.max(1, Math.round(samples.length / ratio));
  const out = new Float32Array(n2);
  for (let i2 = 0; i2 < n2; i2++) {
    const pos = i2 * ratio;
    const i0 = Math.floor(pos);
    const i1 = Math.min(i0 + 1, samples.length - 1);
    const f = pos - i0;
    out[i2] = samples[i0] * (1 - f) + samples[i1] * f;
  }
  return out;
}
function joinParts(parts, pauseSeconds = 0.12) {
  if (!parts.length) return { samples: new Float32Array(0), rate: 22050 };
  const rate = parts[0].rate;
  const pause = Math.round(rate * pauseSeconds);
  const pieces = parts.map((p) => resample(p.samples, p.rate, rate));
  const total = pieces.reduce((s, p) => s + p.length, 0) + pause * (pieces.length - 1);
  const out = new Float32Array(total);
  let off = 0;
  pieces.forEach((p, i2) => {
    out.set(p, off);
    off += p.length;
    if (i2 < pieces.length - 1) off += pause;
  });
  return { samples: out, rate };
}
function encodeWav(samples, rate) {
  const header = 44;
  const buf = new ArrayBuffer(header + samples.length * 2);
  const v = new DataView(buf);
  const w = (o, s) => {
    for (let i2 = 0; i2 < s.length; i2++) v.setUint8(o + i2, s.charCodeAt(i2));
  };
  w(0, "RIFF");
  v.setUint32(4, buf.byteLength - 8, true);
  w(8, "WAVE");
  w(12, "fmt ");
  v.setUint32(16, 16, true);
  v.setUint16(20, 1, true);
  v.setUint16(22, 1, true);
  v.setUint32(24, rate, true);
  v.setUint32(28, rate * 2, true);
  v.setUint16(32, 2, true);
  v.setUint16(34, 16, true);
  w(36, "data");
  v.setUint32(40, samples.length * 2, true);
  let p = header;
  for (let i2 = 0; i2 < samples.length; i2++) {
    const s = Math.max(-1, Math.min(1, samples[i2]));
    v.setInt16(p, s < 0 ? s * 32768 : s * 32767, true);
    p += 2;
  }
  return new Blob([buf], { type: "audio/wav" });
}

