function voicePath(key) {
  const family = key.split("_")[0];
  const region = key.split("-")[0];
  const rest = key.slice(region.length + 1);
  const cut = rest.lastIndexOf("-");
  const name = rest.slice(0, cut);
  const quality = rest.slice(cut + 1);
  return `${family}/${region}/${name}/${quality}/${key}`;
}
function voiceUrls(key) {
  const p = voicePath(key);
  return {
    model: `${HF_BASE}/${p}.onnx`,
    config: `${HF_BASE}/${p}.onnx.json`
  };
}
function voiceFiles(key) {
  return { model: `voices/${key}.onnx`, config: `voices/${key}.onnx.json` };
}

