// src/modules/tts.js
var ttsModule = {
  id: "tts",
  title: "Read aloud",
  load(p) {
    p.audioLib = new AudioLibrary(p);
    p.player = new TtsPlayer(p);
    p.speaker = new Speaker(p, p.player);
  },
  unload(p) {
    p.speaker.destroy();
    p.player.destroy();
  },
  commands: [
    { id: "read-selection", name: "Read selected text aloud", editor: true, run: (p, editor) => p.readSelection(editor) },
    { id: "stop-reading", name: "Stop reading", run: (p) => p.speaker.stop() },
    { id: "toggle-player", name: "Play / pause reading", run: (p) => p.player.toggle() }
  ],
  quick: [{ id: "read", icon: "read", label: "Read the selected text aloud (in a sticky note: puts a \u25B6 there)", run: (p, c) => p.readSelection(c.editor), needsSelection: true }]
};

