    const hid = range0 ? hlIdOfBox(before, range0) : null;
    const cards = st0 ? st0.linked.map((x2) => this.plugin.flash.store.get(x2.id)).filter(Boolean) : [];
    if (cards.some((c) => c.srs && c.srs.state !== "new") && !await confirm(this.app, "This sticky note has a flashcard you have already reviewed. Delete the note and the flashcard?")) return;
    let removed = false;
    let undo = false;
    if (view.getMode && view.getMode() === "source" && view.editor) {
      const ed = view.editor;
      const lines = ed.getValue().split("\n");
      const r = findBoxRange(lines, id);
      if (r) {
        const last = lines.length - 1;
        const atEnd = r.end >= last;
        const from = atEnd && r.start > 0 ? { line: r.start - 1, ch: lines[r.start - 1].length } : { line: r.start, ch: 0 };
        const to = atEnd ? { line: r.end, ch: lines[r.end].length } : { line: r.end + 1, ch: 0 };
        ed.replaceRange("", from, to);
        removed = true;
        undo = true;
      }
    } else {
      await this.app.vault.process(view.file, (text) => {
        const next = removeBoxFromText(text, id);
        removed = next !== text;
        return next;
      });
    }
    if (!removed) {
      new import_obsidian20.Notice("Could not find this box in the note (was it edited?).");
      return;
    }
    if (await this.plugin.audioLib.has(voicePath2)) await this.plugin.removeFile(voicePath2);
    for (const c of cards) this.plugin.flash.store.remove(c.id);
    if (hid && this.plugin.hl) await this.plugin.hl.onBoxDeleted(view.file.path, hid);
