var import_obsidian24 = require("obsidian");
function numberSetting(containerEl, plugin, key, name, desc, min = 1) {
  new import_obsidian24.Setting(containerEl).setName(name).setDesc(desc).addText(
    (t) => t.setValue(String(plugin.settings[key])).onChange(async (v) => {
      const n2 = parseInt(v, 10);
      if (!isNaN(n2) && n2 >= min) {
        plugin.settings[key] = n2;
        await plugin.saveSettings();
        plugin.pomodoro.refresh();
      }
    })
  );
}
function renderPomodoroSettings(containerEl, plugin) {
  const s = plugin.settings;
  new import_obsidian24.Setting(containerEl).setName("Pomodoro timer").setHeading();
  numberSetting(containerEl, plugin, "pomoWork", "Focus (minutes)", "Length of one focus session.");
  numberSetting(containerEl, plugin, "pomoShort", "Short break (minutes)", "");
  numberSetting(containerEl, plugin, "pomoLong", "Long break (minutes)", "");
  numberSetting(containerEl, plugin, "pomoLongEvery", "Long break after", "This many focus sessions.");
  new import_obsidian24.Setting(containerEl).setName("Start the next session automatically").addToggle(
    (t) => t.setValue(s.pomoAutoNext).onChange(async (v) => {
      s.pomoAutoNext = v;
      await plugin.saveSettings();
    })
  );
  new import_obsidian24.Setting(containerEl).setName("Sound when a session ends").addToggle(
    (t) => t.setValue(s.pomoSound).onChange(async (v) => {
      s.pomoSound = v;
      await plugin.saveSettings();
    })
  );
}

