// src/ui/anchors.js
var ANY_MARKER = /<span class="(?:tts|tr)-btn"[^>]*><\/span>/;
var TRAILING_MARKERS = /(?:<span class="(?:tts|tr)-btn"[^>]*><\/span>\s*)+$/;
var CALLOUT_HEAD = /^\s*>\s*\[!/;
function lastMarkerEnd(text) {
  let end = -1;
  const re = /<span class="(?:tts|tr)-btn"[^>]*><\/span>/g;
  let m;
  while (m = re.exec(text)) end = m.index + m[0].length;
  return end;
}
function paragraphBefore(doc, pos) {
  const line = doc.lineAt(pos);
  let cur = line.text.slice(0, pos - line.from);
  cur = cur.replace(TRAILING_MARKERS, "");
  const k = lastMarkerEnd(cur);
  if (k >= 0) return cur.slice(k);
  const parts = [cur];
  for (let n2 = line.number - 1; n2 >= 1; n2--) {
    const t = doc.line(n2).text;
    if (!t.trim() || ANY_MARKER.test(t) || CALLOUT_HEAD.test(t)) break;
    parts.unshift(t);
  }
  return parts.join(" ");
}
function textBeforeButtonDom(btn) {
  const isMarker = (n2) => n2.nodeType === 1 && n2.classList && (n2.classList.contains("tts-btn") || n2.classList.contains("tr-btn"));
  const parts = [];
  let node = btn.previousSibling;
  while (node) {
    if (isMarker(node)) {
      if (parts.join("").trim() === "") {
        node = node.previousSibling;
        continue;
      }
      break;
    }
    parts.unshift(node.textContent || "");
    node = node.previousSibling;
  }
  return parts.join(" ");
}

