function previewBox(parent, kind, title, s) {
  const box = parent.createDiv({ cls: "lc-pbox lc-pbox-" + kind });
  box.createDiv({ cls: "lc-pbox-title", text: title });
  if (kind === "image") {
    box.createDiv({ cls: "lc-pimage", text: "\u{1F5BC}  image" });
    return;
  }
  for (const ln2 of sampleLines(kind, s.srcLangs, s.trans1, s.trans2)) {
    const row = box.createDiv({ cls: "lc-pline " + ROLE_CLASS[ln2.role] + (ln2.lang === "fa" ? " rtl" : "") });
    if (ln2.play && ln2.lang !== "fa") row.createSpan({ cls: "lc-play-demo", text: "\u25B6" });
    row.createSpan({ text: ln2.text });
  }
}
